# Rendered by Ferry for each instance. The route list names every member,
# including this one; NATS ignores the route to itself.
server_name: {{ .Instance.Name }}
listen: 0.0.0.0:4222
http: 0.0.0.0:8222
client_advertise: "{{ .Instance.Host }}:{{ .Instance.Port "client" }}"

jetstream {
  store_dir: /data
  max_memory_store: 64MB
  max_file_store: 1GB
}

cluster {
  name: ferry-nats
  listen: 0.0.0.0:6222
  advertise: "{{ .Instance.Host }}:{{ .Instance.Port "cluster" }}"
  routes: [
{{ range .Role "nats" }}    nats://{{ .Host }}:{{ .Port "cluster" }}
{{ end }}  ]
}

# Rendered by Ferry for each instance. The route list names every member,
# including this one; NATS ignores the route to itself.
server_name: {{ .Instance.Name }}
listen: 0.0.0.0:4222
http: 0.0.0.0:8222
client_advertise: "{{ .Instance.Host }}:{{ .Instance.Port "client" }}"

jetstream {
  store_dir: /data
  max_memory_store: 64MB
  max_file_store: 1GB
}

cluster {
  name: ferry-nats
  listen: 0.0.0.0:6222
  advertise: "{{ .Instance.Host }}:{{ .Instance.Port "cluster" }}"
  routes: [
{{ range .Role "nats" }}    nats://{{ .Host }}:{{ .Port "cluster" }}
{{ end }}  ]
}

# Rendered by Ferry for each load balancer instance: one upstream server per web instance.
upstream ferry_web {
{{ range .Role "web" }}    server {{ .Host }}:{{ .Port "http" }} max_fails=1 fail_timeout=5s;
{{ end }}
}

server {
    listen 80;

    location = /healthz {
        access_log off;
        default_type text/plain;
        return 200 "ok\n";
    }

    location / {
        proxy_pass http://ferry_web;
        proxy_next_upstream error timeout http_502 http_503;
        proxy_connect_timeout 2s;
    }
}
